<?php
/**
 * Optional MediaFlow Proxy Light integration.
 * All credentials stay server-side; the browser receives only an expiring,
 * encrypted playback URL generated by MediaFlow.
 */
final class MediaFlow {
    private static function config() {
        $base = rtrim(trim((string) env_value('MEDIAFLOW_URL', '')), '/');
        $password = trim((string) env_value('MEDIAFLOW_API_PASSWORD', ''));
        $enabled = filter_var(env_value('MEDIAFLOW_ENABLED', '0'), FILTER_VALIDATE_BOOLEAN);
        $parts = $base !== '' ? parse_url($base) : false;
        $scheme = is_array($parts) ? strtolower((string) ($parts['scheme'] ?? '')) : '';
        $host = is_array($parts) ? strtolower((string) ($parts['host'] ?? '')) : '';
        $localHttp = $scheme === 'http' && in_array($host, ['localhost', '127.0.0.1', '::1'], true);
        $validBase = is_array($parts)
            && $host !== ''
            && in_array($scheme, ['https', 'http'], true)
            && ($scheme === 'https' || $localHttp)
            && filter_var($base, FILTER_VALIDATE_URL);

        if (!$validBase) {
            $base = '';
        }

        $ttl = (int) env_value('MEDIAFLOW_URL_TTL', '21600');
        $ttl = max(900, min(86400, $ttl));

        return [
            'enabled' => $enabled && $base !== '' && $password !== '',
            'base' => $base,
            'password' => $password,
            'ttl' => $ttl,
        ];
    }

    public static function isEnabled() {
        $cfg = self::config();
        return $cfg['enabled'];
    }

    public static function urlTtl() {
        $cfg = self::config();
        return $cfg['ttl'];
    }

    public static function createSignedTelegramUrl($telegramUrl) {
        $cfg = self::config();
        if (!$cfg['enabled']) {
            throw new RuntimeException('MediaFlow is not configured');
        }

        $telegramUrl = trim((string) $telegramUrl);
        $parts = parse_url($telegramUrl);
        $host = is_array($parts) ? strtolower((string) ($parts['host'] ?? '')) : '';
        $path = is_array($parts) ? (string) ($parts['path'] ?? '') : '';
        if (!is_array($parts)
            || strtolower((string) ($parts['scheme'] ?? '')) !== 'https'
            || !in_array($host, ['t.me', 'www.t.me', 'telegram.me', 'www.telegram.me'], true)
            || !preg_match('#^/(?:c/\d+|[A-Za-z0-9_]+)/\d+/?$#', $path)) {
            throw new RuntimeException('Not a supported Telegram post URL');
        }
        if (!function_exists('curl_init')) {
            throw new RuntimeException('PHP cURL extension is required');
        }

        $payload = [
            'endpoint' => '/proxy/telegram/stream',
            'params' => ['d' => $telegramUrl],
            'expiration' => $cfg['ttl'],
            'api_password' => $cfg['password'],
        ];
        $json = json_encode($payload, JSON_UNESCAPED_SLASHES);
        if ($json === false) {
            throw new RuntimeException('Could not encode MediaFlow request');
        }

        $headers = [
            'Content-Type: application/json',
            'Accept: application/json',
            'Authorization: Bearer ' . $cfg['password'],
        ];
        $ch = curl_init($cfg['base'] . '/generate_url');
        curl_setopt_array($ch, [
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $json,
            CURLOPT_HTTPHEADER => $headers,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => false,
            CURLOPT_CONNECTTIMEOUT => 4,
            CURLOPT_TIMEOUT => 12,
            CURLOPT_MAXREDIRS => 0,
        ]);
        if (defined('CURLOPT_PROTOCOLS') && defined('CURLPROTO_HTTPS')) {
            $protocols = CURLPROTO_HTTPS;
            $baseParts = parse_url($cfg['base']);
            if (is_array($baseParts)
                && strtolower((string) ($baseParts['scheme'] ?? '')) === 'http') {
                $protocols |= CURLPROTO_HTTP;
            }
            curl_setopt($ch, CURLOPT_PROTOCOLS, $protocols);
        }

        $response = curl_exec($ch);
        $status = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $curlError = curl_error($ch);
        curl_close($ch);

        if (!is_string($response) || $response === '' || $status < 200 || $status >= 300) {
            error_log('[MediaFlow] URL generation failed; HTTP ' . $status
                . ($curlError !== '' ? ' (transport error)' : ''));
            throw new RuntimeException('MediaFlow URL generation failed');
        }

        $data = json_decode($response, true);
        $signedUrl = is_array($data) ? trim((string) ($data['url'] ?? '')) : '';
        $signedParts = $signedUrl !== '' ? parse_url($signedUrl) : false;
        $baseParts = parse_url($cfg['base']);
        $signedHost = is_array($signedParts) ? strtolower((string) ($signedParts['host'] ?? '')) : '';
        $baseHost = is_array($baseParts) ? strtolower((string) ($baseParts['host'] ?? '')) : '';
        $signedScheme = is_array($signedParts) ? strtolower((string) ($signedParts['scheme'] ?? '')) : '';
        $baseScheme = is_array($baseParts) ? strtolower((string) ($baseParts['scheme'] ?? '')) : '';
        $signedPath = is_array($signedParts) ? rtrim((string) ($signedParts['path'] ?? ''), '/') : '';

        if (!is_array($signedParts)
            || $signedHost === ''
            || $signedHost !== $baseHost
            || $signedScheme !== $baseScheme
            || substr($signedPath, -strlen('/proxy/telegram/stream')) !== '/proxy/telegram/stream') {
            throw new RuntimeException('MediaFlow returned an invalid playback URL');
        }
        if (strpos($signedUrl, $cfg['password']) !== false) {
            throw new RuntimeException('MediaFlow URL unexpectedly contains the API password');
        }

        return $signedUrl;
    }
}
